using Godot;

/// <summary>村庄六边形地图的建造预览、右键地块信息和悬停高亮入口。</summary>
public partial class MapInteractionManager : Node
{
    private static readonly Vector2I InvalidCell=new(-9999,-9999);
    private GodotObject? hex_map; private BuildingData? building_data; private WorldEntity? preview; private Vector2I hovered=InvalidCell,buildCell=InvalidCell; private bool building;
    public override void _Ready(){AddToGroup("map_interaction_mgr");CallDeferred(nameof(find_map));}
    private void find_map(){hex_map=GetParent()?.GetNodeOrNull("HexWorldMap") as GodotObject;}
    public override void _UnhandledInput(InputEvent input){if(!GodotObject.IsInstanceValid(hex_map)||hex_map!.Get("game_mode").AsInt32()!=0)return;if(building&&input is InputEventKey {Pressed:true,Keycode:Key.Escape})exit_build_mode();if(input is InputEventMouseButton mouse&&mouse.Pressed){if(building&&mouse.ButtonIndex==MouseButton.Right){exit_build_mode();GetViewport().SetInputAsHandled();return;}if(pointer_over_ui())return;if(mouse.ButtonIndex==MouseButton.Left&&building){if(valid_build_cell(buildCell))place_building(buildCell);}else if(mouse.ButtonIndex==MouseButton.Right)open_info(hex_map.Call("pick_cell_at_world_pos",hex_map.Call("get_global_mouse_position").AsVector2()).AsVector2I());}else if(input is InputEventMouseMotion&&!pointer_over_ui())update_hover();}
    public void enter_build_mode(BuildingData data){if(!GodotObject.IsInstanceValid(hex_map))return;building_data=data;building=true;buildCell=InvalidCell;var scene=ResourceLoader.Load<PackedScene>("res://tscn/entity/building/Building.tscn");preview=scene?.Instantiate<WorldEntity>();if(preview is not null){entity_parent().AddChild(preview);preview.load_from_data(data);preview.Modulate=new(1,1,1,.5f);preview.InputPickable=false;preview.ZIndex=100;preview.Hide();}hex_map!.Call("clear_active_zones");hex_map.Call("clear_select_highlight");}
    public void exit_build_mode(){building=false;building_data=null;buildCell=InvalidCell;preview?.QueueFree();preview=null;if(GodotObject.IsInstanceValid(hex_map)){hex_map!.Call("clear_select_highlight");hex_map.Call("clear_hover_highlight");hex_map.Call("clear_active_zones");}}
    private void update_hover(){var cell=hex_map!.Call("pick_cell_at_world_pos",hex_map.Call("get_global_mouse_position").AsVector2()).AsVector2I();if(building){hex_map.Call("clear_hover_highlight");if(valid_build_cell(cell)){buildCell=cell;hex_map.Call("set_select_highlight",cell);if(preview is not null){preview.GlobalPosition=hex_map.Call("cell_to_world",cell).AsVector2();preview.Show();}}else{buildCell=InvalidCell;hex_map.Call("clear_select_highlight");preview?.Hide();}return;}if(cell==hovered)return;hovered=cell;if(hex_map.Call("is_cell_valid",cell).AsBool())hex_map.Call("set_hover_highlight",cell);else hex_map.Call("clear_hover_highlight");}
    private bool valid_build_cell(Vector2I cell)=>GodotObject.IsInstanceValid(hex_map)&&hex_map!.Call("is_cell_valid",cell).AsBool()&&hex_map.Call("get_terrain_type",cell).AsInt32()==0&&hex_map.Call("get_occupant_at",cell).AsGodotObject() is null;
    private void place_building(Vector2I cell){if(building_data is null||!valid_build_cell(cell))return;var scene=GetTree().CurrentScene;if(scene?.HasMethod("consume_building_cost")==true&&!scene.Call("consume_building_cost",building_data).AsBool())return;var packed=ResourceLoader.Load<PackedScene>("res://tscn/entity/building/Building.tscn");var entity=packed?.Instantiate<Building>();if(entity is null)return;entity_parent().AddChild(entity);entity.load_from_data(building_data);entity.pop_in_animation();hex_map!.Call("register_entity",entity,cell);entity.snap_to_hex_cell(cell,hex_map.Call("cell_to_world",cell).AsVector2());if(scene?.HasMethod("register_built_building")==true)scene.Call("register_built_building",building_data);exit_build_mode();}
    private void open_info(Vector2I cell){if(!hex_map!.Call("is_cell_valid",cell).AsBool())return;foreach(var node in GetTree().GetNodesInGroup("hex_tile_info"))if(node.HasMethod("show_cell_info")){node.Call("show_cell_info",hex_map,cell);break;}}
    private Node entity_parent()=>GetParent()?.GetNodeOrNull<Node>("EntityLayer")??GetParent()??this;
    private bool pointer_over_ui(){var mouse=GetViewport().GetMousePosition();foreach(var group in new[]{"cell_character_list","hex_tile_info","human_info_panel","cultivation_ui_panel","map_overlay_blocker"})foreach(var node in GetTree().GetNodesInGroup(group))if(node is Control control&&control.Visible&&control.GetGlobalRect().HasPoint(mouse))return true;return false;}
}
